insert into public.case_bank
  (title, story, side_a_who, side_a, side_b_who, side_b, clues, answer, explanation, category, source, review_flags, status)
values
  ('The faded-paint deposit', 'A tenant moved out after three years. The landlord kept $400 of the deposit to repaint the flat, pointing to faded walls and a few picture-hook holes.', 'Tenant', 'Faded paint and nail holes after three years is just normal living. Give my deposit back.', 'Landlord', 'The walls need repainting before the next tenant. That costs money, so it comes out of the deposit.', ARRAY['There were no stains, burns or big marks, just fading and small holes.', 'The flat was last painted right before the tenant moved in, three years earlier.', 'The lease said nothing about repainting.']::text[], 'A', 'Deposits cover damage, not normal wear and tear. Paint fading over three years and small picture-hook holes are usually treated as normal wear, so the landlord generally can''t charge for them.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The dog in the vegetable patch', 'A neighbour''s dog kept getting through a gap in the shared fence and dug up a vegetable garden three weekends in a row. The gardener wants $250 for plants and seed.', 'Gardener', 'Your dog wrecked my garden three times. Pay for the plants.', 'Dog owner', 'Dogs dig. You should have fixed the fence if you cared that much.', ARRAY['The gardener told the owner about the gap after the first time.', 'The owner said they''d keep the dog in. They didn''t.', 'The gardener kept receipts and photos for every visit.']::text[], 'A', 'Owners are generally responsible for damage their pets cause, especially after being warned. Being told about the problem and not acting makes the owner''s case much weaker.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The tree that came down', 'A big tree in one garden fell during a storm and crushed the neighbour''s car. The car owner wants the tree owner to pay for repairs.', 'Car owner', 'Your tree, your problem. Pay for my car.', 'Tree owner', 'It was a storm. Nobody can control the weather. Claim it on your insurance.', ARRAY['The storm was strong but not record-breaking.', 'Other trees on the street stayed standing.', 'Six months earlier the car owner sent a letter saying the tree looked dead and was leaning, with photos.']::text[], 'A', 'A healthy tree falling in a storm is usually nobody''s fault. But a tree its owner knew was dead or dangerous is different: ignoring a written warning usually makes the owner responsible.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('Loan or gift?', 'One friend gave another $800 to cover rent. Months later they fell out, and the first friend wants the money back. The other says it was a gift.', 'The lender', 'That was a loan. I want my $800 back.', 'The friend', 'You offered to help. Nobody said anything about paying it back.', ARRAY['Nothing was signed.', 'The day after the money was sent, the friend texted: “I''ll pay you back by June, promise.”', 'June came and went with no payment.']::text[], 'A', 'A loan doesn''t need a signed contract. A message promising to repay is strong evidence it was a loan, not a gift.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('Sold as seen', 'Someone bought a used car privately for $3,000 after a test drive. The ad said “sold as seen”. A week later the gearbox failed and the buyer wants their money back.', 'Buyer', 'It broke a week after I bought it. That''s not fair. Refund me.', 'Seller', 'It drove fine when you tested it and the ad said sold as seen.', ARRAY['The buyer was offered a mechanic''s inspection and said no.', 'There''s no evidence the seller knew about the gearbox problem.', 'The seller never claimed the car was fault-free.']::text[], 'B', 'In a private sale “as seen”, the buyer generally takes the risk of hidden faults, unless the seller lied or hid a problem they knew about.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The builder who never came', 'A homeowner paid a $1,500 deposit for a new patio. Two months later no work had started and the builder stopped replying. The builder says the deposit went on materials.', 'Homeowner', 'You never started. I want my deposit back.', 'Builder', 'I ordered materials with that money. It''s non-refundable.', ARRAY['The contract had a start date, now seven weeks past.', 'Asked for receipts for the materials, the builder sent none.', 'The contract didn''t say the deposit was non-refundable.']::text[], 'A', 'If a builder doesn''t do the work they were paid to do, the customer can usually get the deposit back. Saying it went on materials only helps with proof, like receipts or materials actually delivered.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The broken TV in the van', 'A moving company dropped a TV during a move. The customer wants the full $900 replacement cost. The movers offer $60 under their basic cover.', 'Customer', 'You broke it, you replace it. $900.', 'Movers', 'You turned down full-value insurance. Basic cover pays by weight, so it''s $60.', ARRAY['The quote showed two options: basic cover by weight, or full-value cover for an extra fee.', 'The customer ticked “basic”.', 'The movers admit they dropped it.']::text[], 'B', 'When a customer picks limited cover in writing, movers usually only owe what that cover pays, even when they caused the damage. Full value is what the extra fee buys. Rules differ by country.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The photographer stuck in traffic', 'A wedding photographer arrived 40 minutes late because of a motorway crash and missed the ceremony. They shot the rest of the day. The couple want all $2,000 back.', 'The couple', 'You missed the most important part. We want a full refund.', 'Photographer', 'I missed the ceremony, not the day. I''ll refund that part.', ARRAY['The contract covered eight hours.', 'The photographer worked seven of them and delivered 600 edited photos.', 'The photographer offered back $500.']::text[], 'B', 'Partly doing a job usually means a partial refund, not a full one. The couple got most of what they paid for, so a full refund is unlikely, though the right amount is open to argument.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('Towed from the supermarket', 'A driver parked in a supermarket car park, then walked to a café across the road for two hours. The car was towed and it cost $250 to get it back.', 'Driver', 'Towing a car from a nearly empty car park is a rip-off. I want my $250 back.', 'Car park owner', 'The signs are clear: customers only, two hours, others towed.', ARRAY['There were four large signs, including one at the entrance.', 'The driver didn''t shop at the supermarket.', 'The towing fee matched the amount on the signs.']::text[], 'B', 'Private car parks can usually tow cars that break clearly posted rules, as long as the signs are visible and the fee matches what they say.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The roommate who left early', 'Two roommates signed a one-year lease together. After five months one moved out to live with a partner and stopped paying. The other has been covering the full rent.', 'Roommate who stayed', 'We both signed. You owe your half until the lease ends.', 'Roommate who left', 'I don''t live there any more. Why should I pay for a room I don''t use?', ARRAY['Both names are on the lease.', 'The one who left didn''t find a replacement or ask the landlord to be released.', 'The one who stayed has the bank records for every month.']::text[], 'A', 'When two people sign a lease together, both are usually responsible for the rent until it ends. Moving out doesn''t end that unless the landlord agrees.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The laptop on the last payslip', 'An employee dropped and broke a work laptop. On their last payslip the employer took off $700 for it without asking.', 'Employee', 'You can''t just take money out of my pay. Give it back.', 'Employer', 'You broke company property. It''s only fair you pay for it.', ARRAY['The contract says nothing about paying for damaged equipment.', 'The employee never agreed in writing to the deduction.', 'It was an accident, not carelessness.']::text[], 'A', 'In many places an employer can''t deduct money from wages without written permission or a contract term allowing it. This varies by country and state, so check local rules.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The haircut they hated', 'A customer asked for “a trim and some layers”. At home they decided they hated it and asked for the $80 back. The salon said no.', 'Customer', 'It looks nothing like I wanted. I shouldn''t have to pay.', 'Salon', 'You got the cut you asked for and paid without complaint.', ARRAY['The customer looked in the mirror at the end and said “great, thanks”.', 'They first complained two days later.', 'The salon offered a free fix, which the customer turned down.']::text[], 'B', 'If a service was done as agreed and the customer accepted it at the time, a refund is unlikely. Turning down a free fix also weakens the customer''s case.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The fence on the wrong side', 'A neighbour put up a new fence. A survey later showed it sits 30 cm inside the other neighbour''s land along its whole length.', 'Landowner', 'That fence is on my land. Move it.', 'Fence builder', 'It''s 30 cm. Nobody noticed for a year. Let it go.', ARRAY['The survey was done by a licensed surveyor.', 'The fence went up 14 months ago.', 'The landowner complained in writing as soon as they got the survey.']::text[], 'A', 'Building on someone else''s land isn''t allowed, even by a little. A recent fence that was objected to quickly usually has to come down or move. Very old boundaries can be different.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('Delivered, then gone', 'An online seller shipped a $150 jacket. Tracking shows it was delivered, with a photo of the parcel at the buyer''s front door. The buyer says it was stolen and wants a refund.', 'Buyer', 'I never got it. Refund me.', 'Seller', 'I delivered it to your address and have the photo. Take it up with the police.', ARRAY['The address was the one the buyer gave.', 'The buyer didn''t ask for signature-on-delivery or a safe place.', 'The photo clearly shows the buyer''s door number.']::text[], 'B', 'Once a parcel is delivered correctly to the address the buyer gave, the seller has usually done their part. Theft after that is often the buyer''s loss, though marketplace protection or local consumer law can change that.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The red-light rear-ender', 'Two cars stopped at a light. When it turned green, the front car moved, then braked hard for a cat. The car behind hit it.', 'Front driver', 'You hit me from behind. Your fault.', 'Rear driver', 'You slammed on the brakes for no reason. I couldn''t stop.', ARRAY['Road conditions were dry and clear.', 'The rear car was less than one car length behind.', 'A witness confirms the cat.']::text[], 'A', 'Drivers are expected to leave enough space to stop safely, so the car behind is usually held responsible. Braking for an animal isn''t reckless.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The salad and the steak dinner', 'Six friends went out for a birthday dinner. One ordered a salad and water. Everyone else had steak and cocktails. The bill was split six ways.', 'Salad orderer', 'I had a $14 salad. I''m not paying $65 for your steaks and cocktails.', 'The group', 'We always split evenly. Doing the maths at the table is tacky.', ARRAY['It was a friend''s birthday, so the birthday person paid nothing.', 'The salad orderer had mentioned beforehand they were short on money this month.']::text[], 'jury', null, 'money', 'bank', '{}'::text[], 'draft'),
  ('The leftovers with a name on', 'One roommate labelled a box of leftovers with their name. The other ate it at 2 a.m. after a night out.', 'Label writer', 'My name was literally on it.', 'Late-night eater', 'It was going off tomorrow anyway. I''ll buy you lunch, relax.', ARRAY['The leftovers were from a restaurant birthday dinner.', 'The eater has done this twice before.']::text[], 'jury', null, 'roommates', 'bank', '{}'::text[], 'draft'),
  ('The seat that reclines', 'On a nine-hour flight, someone reclined their seat right after the meal service. The person behind asked them to put it back up.', 'Recliner', 'The seat reclines. I paid for it. It''s a long flight.', 'Person behind', 'I''m 6′4″ and my knees are crushed. Have some decency.', ARRAY['It was a night flight and the cabin lights were off.', 'The person behind was trying to work on a laptop.']::text[], 'jury', null, 'travel', 'bank', '{}'::text[], 'draft'),
  ('Fish in the office microwave', 'A coworker heats leftover fish curry in the shared office microwave every Friday. Others have started complaining about the smell.', 'Fish fan', 'It''s my lunch. It''s a kitchen. I''m allowed to eat food.', 'Coworkers', 'The whole floor smells for an hour. Eat it cold or eat it outside.', ARRAY['There''s no written kitchen policy.', 'The office is open-plan with no windows that open.']::text[], 'jury', null, 'work', 'bank', '{}'::text[], 'draft'),
  ('The borrowed car and the parking fine', 'Someone lent their car to a friend for a weekend. A month later a $90 parking fine arrived for that weekend. The friend says they don''t remember parking there.', 'Car owner', 'It was your weekend with my car. Pay the fine.', 'Friend', 'I don''t remember parking there. Maybe the date''s wrong.', ARRAY['The fine shows a street near the friend''s office.', 'The car owner was out of town that whole weekend.']::text[], 'jury', null, 'friends', 'bank', '{}'::text[], 'draft'),
  ('The gift returned for cash', 'An aunt knitted a jumper for a birthday. Months later she found out it had been given to a charity shop.', 'Aunt', 'I spent weeks on that. The least you could do is keep it.', 'Birthday person', 'A gift is mine to do what I want with. I''m never going to wear it.', ARRAY['The birthday person thanked her warmly at the time.', 'The aunt found out when she saw it in the charity shop window.']::text[], 'jury', null, 'family', 'bank', '{}'::text[], 'draft'),
  ('The birthday party list', 'A parent is throwing a seventh birthday party and has room for ten kids. There are 24 in the class. The child only wants their close friends.', 'Parent', 'We invite who my kid actually plays with. Ten is plenty.', 'Other parents', 'Leaving out most of the class is cruel. Invite everyone or just a few, quietly.', ARRAY['The school asks for whole-class invites if they''re handed out at school.', 'The invitations were handed out in the playground.']::text[], 'jury', null, 'parenting', 'bank', '{}'::text[], 'draft'),
  ('The last slice', 'At a games night, one guest took the last slice of pizza without asking if anyone else wanted it.', 'Slice taker', 'It''s the last slice, not the last lifeboat. Someone had to eat it.', 'The host', 'You always ask before taking the last of something. Basic manners.', ARRAY['The host had bought the pizza.', 'The slice taker had already had four slices.']::text[], 'jury', null, 'friends', 'bank', '{}'::text[], 'draft'),
  ('Saving seats at the gig', 'At a standing-room gig, someone held a spot at the front for three friends who turned up 40 minutes later, blocking other people.', 'Seat saver', 'My friends were running late. We came together, we stand together.', 'Person behind', 'First come, first served. You don''t get to reserve the front.', ARRAY['The friends arrived just before the headline act.', 'The saver was using a jacket and a bag to hold the space.']::text[], 'jury', null, 'events', 'bank', '{}'::text[], 'draft'),
  ('Shoes off at the door', 'A host asks every guest to take their shoes off. One guest at a dinner party refused, saying their outfit doesn''t work without the shoes.', 'Host', 'My house, my rules. Shoes off.', 'Guest', 'It''s a dinner party, not a yoga class. Ask in the invite next time.', ARRAY['The invite didn''t mention it.', 'The host has pale carpet everywhere.']::text[], 'jury', null, 'home', 'bank', '{}'::text[], 'draft'),
  ('No tip for terrible service', 'At a restaurant, food came 50 minutes late and cold, and the server never came back. One diner left no tip. Their partner was embarrassed.', 'Diner', 'Tips are for good service. That wasn''t it.', 'Partner', 'Servers live on tips. Complain to the manager, but you still tip.', ARRAY['It was a country where tipping is expected.', 'The kitchen was clearly short-staffed that night.']::text[], 'jury', null, 'money', 'bank', '{}'::text[], 'draft'),
  ('Ghosted after three dates', 'After three dates, one person stopped replying with no explanation. The other found out from a mutual friend that they''d lost interest.', 'Ghoster', 'Three dates isn''t a relationship. Silence is a clear enough answer.', 'Ghosted', 'A two-line text takes 30 seconds. You owed me that much.', ARRAY['The third date ended with plans for a fourth.', 'The ghoster had said “let''s do this again soon”.']::text[], 'jury', null, 'dating', 'bank', '{}'::text[], 'draft'),
  ('The mother-in-law''s kitchen makeover', 'While babysitting, a mother-in-law reorganised her son and daughter-in-law''s whole kitchen “to make it more practical”.', 'Mother-in-law', 'I was helping. Everything''s easier to find now.', 'Daughter-in-law', 'It''s my kitchen. You don''t rearrange someone''s home without asking.', ARRAY['She also threw away some out-of-date spices.', 'The son thinks it''s genuinely better now.']::text[], 'jury', null, 'family', 'bank', '{}'::text[], 'draft'),
  ('The unflattering photo', 'A friend posted a group photo online. One person in it thinks they look terrible and asked for it to come down. The friend said no.', 'Person in the photo', 'Take it down. I didn''t agree to be posted looking like that.', 'Poster', 'Everyone else looks great. I''m not deleting a good memory over one face.', ARRAY['The poster offered to crop them out instead.', 'The photo already has 200 likes.']::text[], 'jury', null, 'friends', 'bank', '{}'::text[], 'draft'),
  ('Plus-one or not', 'A couple invited a friend to their wedding without a plus-one. The friend has been dating someone for four months and wants to bring them.', 'The couple', 'We''re paying per head. Four months isn''t serious enough.', 'The friend', 'We''re serious. Not inviting my partner is a snub.', ARRAY['The wedding is two months away.', 'Other guests in relationships of a year or more got plus-ones.']::text[], 'jury', null, 'weddings', 'bank', '{}'::text[], 'draft');
